// 자동 생성 파일. src/ 를 고친 뒤 `node build.mjs` 로 다시 만든다.
// 서버(빌드) 쪽 컴포넌트. 빈 상자 하나만 찍고, 나머지는 comments.client.js 가 브라우저에서 그린다.
// 외부 import 없이 preact vnode 를 직접 만든다 (Quartz 는 플러그인 dist 의 외부 의존성을 허용하지 않는다).
// 아래 CSS·스크립트 자리표시자는 build.mjs 가 채운다.

let vnodeId = 0
function h(type, props) {
  return {
    type,
    props,
    key: undefined,
    ref: undefined,
    __k: null,
    __: null,
    __b: 0,
    __e: null,
    __c: null,
    constructor: undefined,
    __v: --vnodeId,
    __i: -1,
    __u: 0,
  }
}

export const HdrComments = (opts) => {
  const apiBase = (opts?.apiBase ?? "").replace(/\/+$/, "")
  const exclude = opts?.exclude ?? []

  const Component = ({ displayClass, fileData }) => {
    const override = fileData.frontmatter?.comments
    const slug = fileData.slug ?? ""
    const excluded = exclude.some((prefix) => slug === prefix || slug.startsWith(prefix + "/"))
    if (override === false || override === "false" || excluded) return null

    return h("section", {
      class: [displayClass, "hdr-comments"].filter(Boolean).join(" "),
      "data-api": apiBase,
      children: h("noscript", { children: "댓글을 보려면 자바스크립트가 필요합니다." }),
    })
  }

  Component.css = ".hdr-comments {\n  margin: 3rem 0 1rem;\n  padding-top: 1.5rem;\n  border-top: 1px solid var(--lightgray);\n}\n\n.hdr-comments-title {\n  margin: 0 0 1rem;\n  font-size: 1.25rem;\n}\n\n.hdr-comments-count {\n  color: var(--gray);\n  font-weight: 400;\n}\n\n.hdr-comments-list {\n  list-style: none;\n  margin: 0 0 1.5rem;\n  padding: 0;\n  display: grid;\n  gap: 0.6rem;\n}\n\n.hdr-comments-empty {\n  color: var(--gray);\n  font-size: 0.95rem;\n}\n\n.hdr-comment {\n  margin: 0;\n  padding: 0.75rem 0.9rem;\n  border: 1px solid var(--lightgray);\n  border-radius: 10px;\n  background: var(--light);\n}\n\n/* 테마에 따라 --highlight 가 불투명한 원색이라(hackthebox) 배경으로 쓰면 글자가 묻힌다 */\n.hdr-comment.is-private {\n  border-style: dashed;\n  border-color: var(--tertiary);\n  background: transparent;\n  background: color-mix(in srgb, var(--tertiary) 7%, transparent);\n}\n\n.hdr-comment.is-hidden {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.25rem 0.6rem;\n  align-items: baseline;\n  color: var(--gray);\n  font-size: 0.9rem;\n  border-style: dashed;\n}\n\n.hdr-comment-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  gap: 0.15rem 0.6rem;\n}\n\n.hdr-comment-name {\n  color: var(--dark);\n  overflow-wrap: anywhere;\n}\n\n.hdr-comment-badge {\n  font-size: 0.72rem;\n  line-height: 1.5;\n  padding: 0 0.5rem;\n  border: 1px solid var(--tertiary);\n  border-radius: 999px;\n  color: var(--tertiary);\n}\n\n.hdr-comment-date {\n  color: var(--gray);\n  font-size: 0.82rem;\n}\n\n.hdr-comment-body {\n  margin: 0.45rem 0 0;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n  line-height: 1.6;\n}\n\n.hdr-comment-delete {\n  margin-left: auto;\n  padding: 0.35rem 0.6rem;\n  border: 0;\n  border-radius: 6px;\n  background: transparent;\n  color: var(--gray);\n  font: inherit;\n  font-size: 0.82rem;\n  cursor: pointer;\n}\n\n.hdr-comment-delete:hover,\n.hdr-comment-delete:focus-visible {\n  color: var(--secondary);\n  text-decoration: underline;\n}\n\n.hdr-comments-form {\n  display: grid;\n  gap: 0.6rem;\n}\n\n/* 16px 미만이면 iOS(인앱 브라우저 포함)가 입력 칸에 초점을 줄 때 화면을 확대한다 */\n.hdr-comments .hdr-comments-name,\n.hdr-comments .hdr-comments-content {\n  box-sizing: border-box;\n  width: 100%;\n  min-width: 0;\n  padding: 0.7rem 0.8rem;\n  border: 1px solid var(--gray);\n  border-radius: 8px;\n  background: var(--light);\n  color: var(--dark);\n  font: inherit;\n  font-size: 16px;\n  line-height: 1.5;\n  -webkit-appearance: none;\n  appearance: none;\n}\n\n.hdr-comments-name {\n  max-width: 20rem;\n}\n\n.hdr-comments-content {\n  min-height: 6.5rem;\n  resize: vertical;\n}\n\n.hdr-comments-name:focus,\n.hdr-comments-content:focus {\n  outline: 2px solid var(--secondary);\n  outline-offset: 1px;\n  border-color: transparent;\n}\n\n.hdr-comments-trap {\n  position: absolute;\n  left: -9999px;\n  width: 1px;\n  height: 1px;\n  opacity: 0;\n}\n\n.hdr-comments-footer {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 0.6rem 1rem;\n}\n\n.hdr-comments-private {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.5rem;\n  min-height: 44px;\n  color: var(--darkgray);\n  font-size: 0.92rem;\n  cursor: pointer;\n}\n\n.hdr-comments-private input {\n  width: 1.15rem;\n  height: 1.15rem;\n  margin: 0;\n  accent-color: var(--secondary);\n}\n\n.hdr-comments-submit {\n  min-height: 44px;\n  padding: 0 1.2rem;\n  border: 0;\n  border-radius: 8px;\n  background: var(--secondary);\n  color: var(--light);\n  font: inherit;\n  font-size: 1rem;\n  font-weight: 600;\n  cursor: pointer;\n}\n\n.hdr-comments-submit:disabled {\n  opacity: 0.55;\n  cursor: default;\n}\n\n.hdr-comments-hint,\n.hdr-comments-status {\n  margin: 0;\n  color: var(--gray);\n  font-size: 0.88rem;\n  line-height: 1.5;\n}\n\n.hdr-comments-hint[hidden] {\n  display: none;\n}\n\n.hdr-comments-status:empty {\n  display: none;\n}\n\n.hdr-comments-status.is-error {\n  color: #d14343;\n}\n\n@media (max-width: 600px) {\n  .hdr-comments-name {\n    max-width: none;\n  }\n\n  .hdr-comments-footer {\n    flex-direction: column;\n    align-items: stretch;\n  }\n\n  .hdr-comments-submit {\n    width: 100%;\n  }\n}\n"
  Component.afterDOMLoaded = "// 댓글 위젯 (브라우저에서 실행). build.mjs 가 이 파일을 문자열로 dist 에 넣는다.\n// Quartz 는 SPA 라서 페이지를 옮길 때마다 \"nav\" 이벤트가 오고, 그때 다시 그린다.\n;(function () {\n  var TOKEN_KEY = \"hdr-comments-token\"\n  var NAME_KEY = \"hdr-comments-name\"\n  var memory = {} // localStorage 가 막힌 브라우저(일부 인앱·사생활 보호 모드)용\n\n  function storeGet(key) {\n    try {\n      var v = window.localStorage.getItem(key)\n      if (v !== null) return v\n    } catch (e) {}\n    return memory[key] || null\n  }\n\n  function storeSet(key, value) {\n    memory[key] = value\n    try {\n      window.localStorage.setItem(key, value)\n      return window.localStorage.getItem(key) === value\n    } catch (e) {\n      return false\n    }\n  }\n\n  // 쿠키 대신 쓰는 작성자 식별 토큰. 서버에는 해시만 저장된다.\n  function authorToken() {\n    var token = storeGet(TOKEN_KEY)\n    if (token && /^[a-f0-9]{64}$/.test(token)) return token\n    var bytes = new Uint8Array(32)\n    window.crypto.getRandomValues(bytes)\n    token = \"\"\n    for (var i = 0; i < bytes.length; i++) token += (\"0\" + bytes[i].toString(16)).slice(-2)\n    storeSet(TOKEN_KEY, token)\n    return token\n  }\n\n  function storagePersists() {\n    return storeSet(\"hdr-comments-probe\", \"1\")\n  }\n\n  // Worker 의 normalizePage() 와 같은 규칙이어야 한다\n  function pageKey() {\n    var p = window.location.pathname\n    try {\n      p = decodeURIComponent(p)\n    } catch (e) {}\n    p = p.normalize(\"NFC\")\n    p = p.replace(/\\/index(\\.html)?$/, \"/\").replace(/\\.html$/, \"\")\n    if (p.length > 1) p = p.replace(/\\/+$/, \"\")\n    return p\n  }\n\n  function el(tag, cls, text) {\n    var node = document.createElement(tag)\n    if (cls) node.className = cls\n    if (text != null) node.textContent = text\n    return node\n  }\n\n  function formatDate(iso) {\n    var d = new Date(iso)\n    if (isNaN(d)) return \"\"\n    try {\n      return d.toLocaleString(\"ko-KR\", { dateStyle: \"medium\", timeStyle: \"short\" })\n    } catch (e) {\n      return d.toLocaleString()\n    }\n  }\n\n  function request(api, method, path, body) {\n    var headers = { \"X-Author-Token\": authorToken() }\n    if (body) headers[\"Content-Type\"] = \"application/json\"\n    return fetch(api + path, {\n      method: method,\n      headers: headers,\n      body: body ? JSON.stringify(body) : undefined,\n      credentials: \"omit\",\n      cache: \"no-store\",\n    }).then(function (res) {\n      return res\n        .json()\n        .catch(function () {\n          return {}\n        })\n        .then(function (data) {\n          if (!res.ok) throw new Error(data.error || \"요청에 실패했습니다.\")\n          return data\n        })\n    })\n  }\n\n  function mount(root) {\n    var api = (root.getAttribute(\"data-api\") || \"\").replace(/\\/+$/, \"\")\n    var page = pageKey()\n    root.textContent = \"\"\n\n    var title = el(\"h2\", \"hdr-comments-title\", \"댓글\")\n    var count = el(\"span\", \"hdr-comments-count\")\n    title.appendChild(count)\n    root.appendChild(title)\n\n    var list = el(\"ul\", \"hdr-comments-list\")\n    root.appendChild(list)\n\n    if (!api) {\n      list.appendChild(el(\"li\", \"hdr-comments-empty\", \"댓글 서버가 설정되지 않았습니다.\"))\n      return\n    }\n\n    // ---- 작성 폼 ----------------------------------------------------------\n    var form = el(\"form\", \"hdr-comments-form\")\n    form.setAttribute(\"novalidate\", \"\")\n\n    var nameInput = el(\"input\", \"hdr-comments-name\")\n    nameInput.type = \"text\"\n    nameInput.name = \"name\"\n    nameInput.required = true\n    nameInput.maxLength = 40\n    nameInput.placeholder = \"이름 (필수)\"\n    nameInput.setAttribute(\"aria-label\", \"이름\")\n    nameInput.autocomplete = \"nickname\"\n    nameInput.value = storeGet(NAME_KEY) || \"\"\n\n    var contentInput = el(\"textarea\", \"hdr-comments-content\")\n    contentInput.name = \"content\"\n    contentInput.required = true\n    contentInput.maxLength = 2000\n    contentInput.rows = 4\n    contentInput.placeholder = \"댓글을 남겨 주세요\"\n    contentInput.setAttribute(\"aria-label\", \"댓글 내용\")\n\n    // 허니팟: 사람에게는 보이지 않는 칸. 봇이 채우면 서버가 버린다.\n    var trap = el(\"input\", \"hdr-comments-trap\")\n    trap.type = \"text\"\n    trap.name = \"website\"\n    trap.tabIndex = -1\n    trap.autocomplete = \"off\"\n    trap.setAttribute(\"aria-hidden\", \"true\")\n\n    var privateLabel = el(\"label\", \"hdr-comments-private\")\n    var privateInput = el(\"input\")\n    privateInput.type = \"checkbox\"\n    privateInput.name = \"is_private\"\n    privateLabel.appendChild(privateInput)\n    privateLabel.appendChild(el(\"span\", null, \"비공개 (나와 관리자만 볼 수 있음)\"))\n\n    var hint = el(\"p\", \"hdr-comments-hint\")\n    hint.hidden = true\n\n    var submit = el(\"button\", \"hdr-comments-submit\", \"댓글 남기기\")\n    submit.type = \"submit\"\n\n    var status = el(\"p\", \"hdr-comments-status\")\n    status.setAttribute(\"role\", \"status\")\n    status.setAttribute(\"aria-live\", \"polite\")\n\n    var footer = el(\"div\", \"hdr-comments-footer\")\n    footer.appendChild(privateLabel)\n    footer.appendChild(submit)\n\n    form.appendChild(nameInput)\n    form.appendChild(contentInput)\n    form.appendChild(trap)\n    form.appendChild(footer)\n    form.appendChild(hint)\n    form.appendChild(status)\n    root.appendChild(form)\n\n    privateInput.addEventListener(\"change\", function () {\n      hint.hidden = !privateInput.checked\n      if (!privateInput.checked) return\n      hint.textContent = storagePersists()\n        ? \"비공개 댓글은 지금 쓰는 이 브라우저에서만 다시 볼 수 있습니다. 카카오톡·인스타그램 안에서 열었다면, 다음에도 같은 앱 안에서 열어야 보입니다.\"\n        : \"이 브라우저는 기록을 저장하지 못해, 비공개 댓글은 이 페이지를 떠나면 다시 볼 수 없습니다. 관리자에게는 전달됩니다.\"\n    })\n\n    // ---- 목록 -------------------------------------------------------------\n    function setStatus(text, isError) {\n      status.textContent = text || \"\"\n      status.classList.toggle(\"is-error\", !!isError)\n    }\n\n    function renderItem(c) {\n      var li = el(\"li\", \"hdr-comment\")\n      if (c.hidden) {\n        li.classList.add(\"is-hidden\")\n        li.appendChild(el(\"span\", \"hdr-comment-lock\", \"비공개 댓글입니다.\"))\n        li.appendChild(el(\"time\", \"hdr-comment-date\", formatDate(c.created_at)))\n        return li\n      }\n\n      if (c.is_private) li.classList.add(\"is-private\")\n      var head = el(\"div\", \"hdr-comment-head\")\n      head.appendChild(el(\"strong\", \"hdr-comment-name\", c.name))\n      if (c.is_private) head.appendChild(el(\"span\", \"hdr-comment-badge\", \"비공개\"))\n      var time = el(\"time\", \"hdr-comment-date\", formatDate(c.created_at))\n      time.dateTime = c.created_at\n      head.appendChild(time)\n      li.appendChild(head)\n\n      // textContent 로만 넣는다: 댓글에 든 HTML 은 글자 그대로 보인다\n      li.appendChild(el(\"p\", \"hdr-comment-body\", c.content))\n\n      if (c.mine) {\n        var del = el(\"button\", \"hdr-comment-delete\", \"삭제\")\n        del.type = \"button\"\n        del.addEventListener(\"click\", function () {\n          if (!window.confirm(\"이 댓글을 삭제할까요?\")) return\n          del.disabled = true\n          request(api, \"DELETE\", \"/api/comments/\" + c.id)\n            .then(load)\n            .catch(function (err) {\n              del.disabled = false\n              setStatus(err.message, true)\n            })\n        })\n        head.appendChild(del)\n      }\n      return li\n    }\n\n    function render(comments) {\n      list.textContent = \"\"\n      count.textContent = comments.length ? \" \" + comments.length : \"\"\n      if (!comments.length) {\n        list.appendChild(el(\"li\", \"hdr-comments-empty\", \"아직 댓글이 없습니다. 첫 댓글을 남겨 보세요.\"))\n        return\n      }\n      comments.forEach(function (c) {\n        list.appendChild(renderItem(c))\n      })\n    }\n\n    function load() {\n      return request(api, \"GET\", \"/api/comments?page=\" + encodeURIComponent(page))\n        .then(function (data) {\n          // 응답을 기다리는 사이 다른 페이지로 옮겨 갔으면 버린다\n          if (!root.isConnected || page !== pageKey()) return\n          render(data.comments || [])\n        })\n        .catch(function () {\n          if (!root.isConnected) return\n          list.textContent = \"\"\n          list.appendChild(el(\"li\", \"hdr-comments-empty\", \"댓글을 불러오지 못했습니다.\"))\n        })\n    }\n\n    form.addEventListener(\"submit\", function (e) {\n      e.preventDefault()\n      var name = nameInput.value.trim()\n      var content = contentInput.value.trim()\n      if (!name) {\n        setStatus(\"이름을 입력해 주세요.\", true)\n        nameInput.focus()\n        return\n      }\n      if (!content) {\n        setStatus(\"내용을 입력해 주세요.\", true)\n        contentInput.focus()\n        return\n      }\n\n      submit.disabled = true\n      setStatus(\"보내는 중…\")\n      request(api, \"POST\", \"/api/comments\", {\n        page: page,\n        name: name,\n        content: content,\n        is_private: privateInput.checked,\n        website: trap.value,\n      })\n        .then(function () {\n          storeSet(NAME_KEY, name)\n          contentInput.value = \"\"\n          setStatus(privateInput.checked ? \"비공개 댓글을 남겼습니다.\" : \"댓글을 남겼습니다.\")\n          return load()\n        })\n        .catch(function (err) {\n          setStatus(err.message || \"댓글을 보내지 못했습니다.\", true)\n        })\n        .then(function () {\n          submit.disabled = false\n        })\n    })\n\n    load()\n  }\n\n  function init() {\n    var roots = document.querySelectorAll(\".hdr-comments\")\n    for (var i = 0; i < roots.length; i++) mount(roots[i])\n  }\n\n  document.addEventListener(\"nav\", init)\n})()\n"
  return Component
}
